    /**
     * @param array $projectEMUsage
     */
    public function setProjectEMUsage(): void
    {
        try {
            $projectEMUsage = array();

            if ($this->getRefreshProjectId()) {
                $q = $this->query("select
                       rems.external_module_id,
                       rem.directory_prefix as module_prefix,
                       rems.project_id,
                       rp.app_title as project_title,
                       rp.status,
                       rrc.record_count,
                       sum(case when rems.`key` = 'enabled' and rems.value = 'true' then 1 else 0 end) as is_em_enabled,
                       count(*) as number_of_settings_rows
                    from redcap_external_module_settings rems
                    join redcap_external_modules rem on rems.external_module_id = rem.external_module_id
                    join redcap_projects rp on rems.project_id = rp.project_id
                    join redcap_record_counts rrc on rp.project_id = rrc.project_id
                    where rems.project_id = ?
                    group by rems.external_module_id, rems.project_id, rem.directory_prefix, rp.app_title, rp.status, rrc.record_count having
                    -- rp.status = 1            -- is production
                    -- and is_em_enabled = 1 -- is enabled
                     number_of_settings_rows > 0  -- has actual data", [$this->getRefreshProjectId()]);
            } else {
                $q = $this->query("select
                       rems.external_module_id,
                       rem.directory_prefix as module_prefix,
                       rems.project_id,
                       rp.app_title as project_title,
                       rp.status,
                       rrc.record_count,
                       sum(case when rems.`key` = 'enabled' and rems.value = 'true' then 1 else 0 end) as is_em_enabled,
                       count(*) as number_of_settings_rows
                    from redcap_external_module_settings rems
                    join redcap_external_modules rem on rems.external_module_id = rem.external_module_id
                    join redcap_projects rp on rems.project_id = rp.project_id
                    join redcap_record_counts rrc on rp.project_id = rrc.project_id
                    where rems.project_id is not null
                    group by rems.external_module_id, rems.project_id, rem.directory_prefix, rp.app_title, rp.status, rrc.record_count having
                    rp.status = 1            -- is production
                    -- and is_em_enabled = 1 -- is enabled
                    and number_of_settings_rows > 0  -- has actual data", []);
            }


            while ($row = db_fetch_assoc($q)) {
                $linkedQ = $this->query("SELECT t.value
                            FROM redcap_external_module_settings t
                            WHERE project_id = ? and `key` = 'linked-project'", [$row['project_id']]);

                $linkedRow = db_fetch_assoc($linkedQ);
                if ($linkedRow['value'] && $linkedRow['value'] != '') {
                    $v = json_decode($linkedRow['value'], true);
                    $ritPID = array_key_first($v);
                } else {
                    $ritPID = null;
                }

                $em = $row;
                $em['redcap'] = $this->getExternalModulesREDCapRecords()[$row['module_prefix']];
                $em['entity'] = array(
                    'module_prefix' => $row['module_prefix'],
                    'project_id' => $row['project_id'],
                    'project_title' => $row['project_title'],
                    'rit_portal_project_id' => $ritPID,
                    'status' => (string)$row['status'],
                    'record_count' => $row['record_count'],
                    'is_em_enabled' => $row['is_em_enabled'],
                    'maintenance_fees' => $em['redcap'][$this->getFirstEventId()]['actual_monthly_cost'],
                    'has_maintenance_fees' => $em['redcap'][$this->getFirstEventId()]['maintenance_fee'],
                    'number_of_settings_rows' => $row['number_of_settings_rows'],
                );
                $projectEMUsage[] = $em;
            }
            $this->projectEMUsage = $projectEMUsage;
        } catch (\Exception $e) {
            echo $e->getMessage();
        }

    }

    public function processRequest()
    {
        if (!isset($_POST) or empty($_POST)) {
            throw new \LogicException("you are not allowed to access the API");
        }

        if (!isset($_POST['secret_token']) || !isset($_POST['request'])) {
            throw new \LogicException("request parameter is missing");
        }

        $token = filter_var($_POST['secret_token'], FILTER_SANITIZE_STRING);
        if (!$this->verifyToken($token)) {
            throw new \LogicException("wrong token provided");
        }

        // set request
        $this->setRequest(filter_var($_POST['request'], FILTER_SANITIZE_STRING));

        if ($this->getRequest() == 'em_utilization') {
            $this->createExternalModuleUtilizationLogs($this->getFirstEventId());
        }
        if ($this->getRequest() == 'project_em_usage') {
            $this->createProjectsExternalModuleUsageLogs();
        }

        if ($this->getRequest() == 'em_monthly_charges') {
            $this->getEMMonthlyChargesRecords();
        }

        if ($this->getRequest() == 'custom_charges') {
            $this->getCustomMonthlyChargesRecords();
        }
    }

    public function processCron()
    {
        if ($_GET['name'] == 'em_utilization') {
            $this->processEMUtilization();
        }
        if ($_GET['name'] == 'project_em_usage') {
            $this->processProjectEMUsage();
        }

        if ($_GET['name'] == 'em_monthly_charges') {
            $this->processEMMonthlyCharges();
        }
    }

