    public function getEMUtilizationRecordDoNotMatchREDCapProjectRecords()
    {
        $date = strtotime($this->getUnixTimestampForLastCron());

        $query = "select
id ,instance, module_prefix, version, FROM_UNIXTIME(`date`, '%Y-%m-%d') as `date` , globally_enabled, discoverable_in_project, user_activate_permission, total_enabled_projects, total_enabled_dev_projects, total_enabled_prod_projects, total_using_projects ,maintenance_fees
 from redcap_entity_external_modules_utilization where date >= $date";
        $q = db_query($query);
        $result = [];
        while ($row = db_fetch_assoc($q)) {
            $redcapRecord = $this->getExternalModulesREDCapRecords()[$row['module_prefix']];
            if ($redcapRecord[$this->getFirstEventId()]['module_global'] != $row['globally_enabled'] || $redcapRecord[$this->getFirstEventId()]['module_discoverable'] != $row['discoverable_in_project'] || $redcapRecord[$this->getFirstEventId()]['module_self_enable'] != $row['user_activate_permission']) {
                if ($redcapRecord[$this->getFirstEventId()]['module_global'] != $row['globally_enabled']) {
                    $row['globally_enabled'] = '<div class="alert alert-danger">' . $row['globally_enabled'] . '</div>';
                }
                if ($redcapRecord[$this->getFirstEventId()]['module_discoverable'] != $row['discoverable_in_project']) {
                    $row['discoverable_in_project'] = '<div class="alert alert-danger">' . $row['discoverable_in_project'] . '</div>';
                }
                if ($redcapRecord[$this->getFirstEventId()]['module_self_enable'] != $row['user_activate_permission']) {
                    $row['user_activate_permission'] = '<div class="alert alert-danger">' . $row['user_activate_permission'] . '</div>';
                }
                $result[] = $row;
            }

        }
        return $result;
    }

    public function prepareEntityColumns($entityName, $columns)
    {
        $entities = $this->redcap_entity_types();
        $result = array();
        if (!key_exists($entityName, $entities)) {
            throw new \Exception("entity $entityName not found in defined entities.");
        } else {
            $properties = $entities[$entityName]['properties'];
            foreach ($properties as $key => $property) {
                if (in_array($key, $columns)) {
                    $index = array_search($key, $columns);
                    $columns[$index] = $property['name'];
                }
            }
        }


        foreach ($columns as $column) {
            $result[] = array('title' => $column);
        }
        return $result;
    }

    public function processEMMonthlyCharges()
    {
        $factory = $this->getEntityFactory();
        foreach ($this->getInstances() as $id => $instance) {
            $body = $this->getInstanceEMBody('em_monthly_charges', $instance['service-url']);
            if ($body) {
                foreach ($body as $record) {
                    $record['entity']['instance'] = $instance['name'];
                    if ($record['entity']['is_em_enabled'] && !$this->getProjectEMMonthlyCharge($record['entity'])) {
                        $data = array(
                            'instance' => $instance['name'],
                            'project_id' => $record['entity']['project_id'],
                            'module_prefix' => $record['entity']['module_prefix'],
                            'has_maintenance_fees' => $record['entity']['has_maintenance_fees']?1:0,
                            'maintenance_fees' => ($record['entity']['maintenance_fees'] AND $record['entity']['has_maintenance_fees'])?$record['entity']['maintenance_fees']: 0,
                            'charge_month' => date('m'),
                            'charge_year' => date('Y'),
                        );
                        $entity = $factory->create('external_modules_charges', $data);
                        if (!$entity && $factory->errors) {
                            $this->emError("Could not create EM Monthly Charge for REDCap PID#" . $data['project_id'] . " for EM " . $data['module_prefix']);
                            $key_value_pairs = [];
                            foreach ($factory->errors as $key => $value) {
                                $key_value_pairs[] = "$key: $value";
                            }

                            // Implode the key-value pairs into a string, separated by commas
                            $result = implode(', ', $key_value_pairs);
                            $this->emError($result);
                        } else {
                            $this->emLog("EM Monthly Charge record was created for REDCap PID#" . $data['project_id'] . " for EM " . $data['module_prefix']);
                        }
                    }
                }
            }
        }
    }

