    {
        $total = 0;
        foreach ($this->getProjectCustomCharges($projectId) as $charge) {
            $total += $charge['amount'];
        }
        return $total;
    }

    /**
     * @param $projectId
     * @return array
     */
    public function getProjectCustomCharges($projectId)
    {
        $result = [];
        foreach ($this->getCustomCharges() as $charge) {
            if ($charge['project_id'] == $projectId) {
                $result[] = $charge;
            }
        }

        return $result;
    }

    /**
     * @return mixed
     */
    public function getCustomCharges()
    {
        if (!$this->customCharges) {
            $this->setCustomCharges();
        }
        return $this->customCharges;
    }

    /**
     * @param mixed $customCharges
     */
    public function setCustomCharges(): void
    {
        $charges = array();
        $q = $this->query("SELECT * FROM redcap_entity_custom_charges WHERE status  = 1 ", []);

        while ($row = db_fetch_assoc($q)) {
            $charges[] = $row;
        }
        $this->customCharges = $charges;
    }

    // =========================================================================
    //  PTA & Monthly Finance Report Methods
    // =========================================================================

    /**
     * Get all PTA accounts
     * @return array
     */
    public function getAllPTAAccounts()
    {
        $entities = $this->getEntityFactory()->query('pta_accounts')->execute();
        $result = [];
        if ($entities) {
            foreach ($entities as $entity) {
                $data = $entity->getData();
                $data['id'] = $entity->getId();
                $result[] = $data;
            }
        }
        return $result;
    }

    /**
     * Get a single PTA account by entity ID
     * @param int $ptaEntityId
     * @return array|false
     */
    public function getPTAAccount($ptaEntityId)
    {
        $entity = $this->getEntityFactory()->getInstance('pta_accounts', $ptaEntityId);
        if ($entity) {
            $data = $entity->getData();
            $data['id'] = $entity->getId();
            return $data;
        }
        return false;
    }

    /**
     * Create or update a PTA account
     * @param array $data
     * @return int|false  entity id on success
     */
    public function savePTAAccount($data)
    {
        $factory = $this->getEntityFactory();
        if (!empty($data['id'])) {
            $entity = $factory->getInstance('pta_accounts', $data['id']);
            if ($entity) {
                unset($data['id']);
                if ($entity->setData($data)) {
                    $entity->save();
                    return $entity->getId();
                }
            }
            return false;
        }
        $entity = $factory->create('pta_accounts', $data);
        return $entity ? $entity->getId() : false;
    }

    /**
     * Get all project-PTA mappings, optionally filtered by project or PTA
     * @param int|null $projectId
     * @param int|null $ptaEntityId
     * @return array
     */
    public function getProjectPTAMappings($projectId = null, $ptaEntityId = null)
    {
        $query = $this->getEntityFactory()->query('project_pta_mapping');
        if ($projectId) {
            $query->condition('project_id', $projectId);
        }
        if ($ptaEntityId) {
            $query->condition('pta_id', $ptaEntityId);
        }
        $entities = $query->execute();
        $result = [];
        if ($entities) {
            foreach ($entities as $entity) {
                $data = $entity->getData();
                $data['id'] = $entity->getId();
                $result[] = $data;
            }
        }
        return $result;
    }

    /**
     * Assign a PTA to a project
     * @param int $projectId
     * @param int $ptaEntityId
     * @param string $ptaNumber
     * @return int|false
     */
    public function assignPTAToProject($projectId, $ptaEntityId, $ptaNumber)
    {
        // Check if mapping already exists
        $existing = $this->getProjectPTAMappings($projectId, $ptaEntityId);
        if (!empty($existing)) {
            return $existing[0]['id']; // already mapped
        }
        $entity = $this->getEntityFactory()->create('project_pta_mapping', [
            'project_id' => $projectId,
            'pta_id' => $ptaEntityId,
            'pta_number' => $ptaNumber,
            'active' => 1,
        ]);
        return $entity ? $entity->getId() : false;
    }

    /**
     * Remove a project-PTA mapping
     * @param int $mappingId
     * @return bool
     */
    public function removePTAFromProject($mappingId)
    {
        $entity = $this->getEntityFactory()->getInstance('project_pta_mapping', $mappingId);
        if ($entity) {
            $entity->delete();
            return true;
        }
        return false;
    }

    /**
     * Generate the monthly PTA charges report for a given month/year.
     * Aggregates charges from external_modules_charges grouped by PTA.
     *
     * @param int $month
     * @param int $year
     * @return array  The full report structure
     */
    public function generateMonthlyPTAReport($month, $year)
    {
        // 1. Get all charges for the given month/year
        $chargesQuery = $this->getEntityFactory()->query('external_modules_charges')
            ->condition('charge_month', (int)$month)
            ->condition('charge_year', (int)$year);
        $chargeEntities = $chargesQuery->execute();

        // Build a lookup: project_id => [ charges ]
        $projectCharges = [];
        if ($chargeEntities) {
            foreach ($chargeEntities as $ce) {
                $cd = $ce->getData();
                $cd['id'] = $ce->getId();
                $pid = $cd['project_id'];
                if (!isset($projectCharges[$pid])) {
                    $projectCharges[$pid] = [];
                }
                $projectCharges[$pid][] = $cd;
            }
        }

        // 2. Get all project-PTA mappings
        $allMappings = $this->getProjectPTAMappings();
        // Build lookup: project_id => pta_number
        $projectPTA = [];
        foreach ($allMappings as $m) {
            if ($m['active']) {
                $projectPTA[$m['project_id']] = $m['pta_number'];
            }
        }

        // 3. Get project titles
        $projectTitles = [];
        $allProjectIds = array_unique(array_merge(array_keys($projectCharges), array_keys($projectPTA)));
        foreach ($allProjectIds as $pid) {
            $projectTitles[$pid] = $this->getProjectTitle($pid);
        }

        // 4. Build report data grouped by PTA
        $ptaGroups = [];
        $unmappedProjects = [];

        foreach ($projectCharges as $pid => $charges) {
            $ptaNumber = $projectPTA[$pid] ?? null;
            if (!$ptaNumber) {
                // Project has no PTA assigned – put under "Unmapped"
                $ptaNumber = '__UNMAPPED__';
            }
            if (!isset($ptaGroups[$ptaNumber])) {
                $ptaGroups[$ptaNumber] = [
                    'pta_number' => $ptaNumber === '__UNMAPPED__' ? 'Unmapped' : $ptaNumber,
                    'total_charges' => 0,
                    'projects' => [],
                ];
            }

            // Sum up charges per project
            $projectTotal = 0;
            $emDetails = [];
            foreach ($charges as $c) {
                $fee = (int)($c['maintenance_fees'] ?? 0);
                $projectTotal += $fee;
                $emDetails[] = [
                    'module_prefix' => $c['module_prefix'],
                    'maintenance_fees' => $fee,
                    'has_maintenance_fees' => $c['has_maintenance_fees'] ?? 0,
                    'instance' => $c['instance'] ?? '',
                ];
            }
            $ptaGroups[$ptaNumber]['total_charges'] += $projectTotal;
            $ptaGroups[$ptaNumber]['projects'][] = [
                'project_id' => $pid,
                'project_title' => $projectTitles[$pid] ?? "Project #$pid",
                'total_charges' => $projectTotal,
                'external_modules' => $emDetails,
            ];
        }

        // Sort PTA groups: Unmapped last
        uksort($ptaGroups, function ($a, $b) {
            if ($a === '__UNMAPPED__') return 1;
            if ($b === '__UNMAPPED__') return -1;
            return strcmp($a, $b);
        });

        $grandTotal = 0;
        foreach ($ptaGroups as &$g) {
            $grandTotal += $g['total_charges'];
        }
        unset($g);

        return [
            'month' => (int)$month,
            'year' => (int)$year,
            'generated_at' => date('Y-m-d H:i:s'),
            'grand_total' => $grandTotal,
            'pta_groups' => array_values($ptaGroups),
        ];
    }

    /**
     * Helper to get project title by ID
     * @param int $pid
     * @return string
     */
    private function getProjectTitle($pid)
    {
        $q = $this->query("SELECT app_title FROM redcap_projects WHERE project_id = ?", [$pid]);
        $row = db_fetch_assoc($q);
        return $row ? $row['app_title'] : "Project #$pid";
    }

    /**
     * Persist a generated monthly PTA report
     *
     * @param int $month
     * @param int $year
     * @param bool $regenerate  If true, replaces an existing report for the same month/year
     * @return array ['report_id' => int, 'report' => array]
     */
    public function saveMonthlyPTAReport($month, $year, $regenerate = false)
    {
        // Check if a report already exists for this month/year
        $existing = $this->getEntityFactory()->query('monthly_pta_reports')
            ->condition('report_month', (int)$month)
            ->condition('report_year', (int)$year)
            ->execute();

        $report = $this->generateMonthlyPTAReport($month, $year);
        $currentUser = defined('USERID') ? USERID : 'system';

        if ($existing && !$regenerate) {
            $entity = array_pop($existing);
            $data = $entity->getData();
            $data['id'] = $entity->getId();
            return [
                'report_id' => $entity->getId(),
                'report' => json_decode($data['report_data'], true),
                'already_exists' => true,
            ];
        }

        $entityData = [
            'report_month' => (int)$month,
            'report_year' => (int)$year,
            'generated_at' => time(),
            'generated_by' => $currentUser,
            'report_data' => json_encode($report),
            'total_charges' => $report['grand_total'],
            'status' => 'draft',
        ];

        if ($existing && $regenerate) {
            // Update existing
            $entity = array_pop($existing);
            if ($entity->setData($entityData)) {
                $entity->save();
                return [
                    'report_id' => $entity->getId(),
                    'report' => $report,
                    'regenerated' => true,
                ];
            }
            return ['error' => 'Failed to update existing report'];
        }

        // Create new
        $entity = $this->getEntityFactory()->create('monthly_pta_reports', $entityData);
        if ($entity) {
            return [
                'report_id' => $entity->getId(),
                'report' => $report,
            ];
        }
        return ['error' => 'Failed to create report'];
    }

    /**
     * Get a previously saved monthly report
     * @param int $reportId  Entity ID
     * @return array|false
     */
    public function getMonthlyPTAReportById($reportId)
    {
        $entity = $this->getEntityFactory()->getInstance('monthly_pta_reports', $reportId);
        if ($entity) {
            $data = $entity->getData();
            $data['id'] = $entity->getId();
            $data['report_data'] = json_decode($data['report_data'], true);
            return $data;
        }
        return false;
    }

    /**
     * List all saved monthly PTA reports (meta only, no full JSON)
     * @return array
     */
    public function listMonthlyPTAReports()
    {
        $entities = $this->getEntityFactory()->query('monthly_pta_reports')->execute();
        $result = [];
        if ($entities) {
            foreach ($entities as $entity) {
                $data = $entity->getData();
                $result[] = [
                    'id' => $entity->getId(),
                    'report_month' => $data['report_month'],
                    'report_year' => $data['report_year'],
                    'generated_at' => $data['generated_at'],
                    'generated_by' => $data['generated_by'],
                    'total_charges' => $data['total_charges'],
                    'status' => $data['status'],
                ];
            }
        }
        // Sort by year desc, month desc
        usort($result, function ($a, $b) {
            if ($a['report_year'] !== $b['report_year']) {
                return $b['report_year'] - $a['report_year'];
            }
            return $b['report_month'] - $a['report_month'];
        });
        return $result;
    }

    /**
     * Export a monthly report as CSV string
     * @param int $reportId
     * @return string CSV content
     */
    public function exportMonthlyPTAReportCSV($reportId)
    {
        $report = $this->getMonthlyPTAReportById($reportId);
        if (!$report) {
            return '';
        }

        $reportData = $report['report_data'];
        $lines = [];
        $lines[] = ['PTA Number', 'Project ID', 'Project Title', 'Module Prefix', 'Maintenance Fees', 'Instance'];

        if (!empty($reportData['pta_groups'])) {
            foreach ($reportData['pta_groups'] as $ptaGroup) {
                foreach ($ptaGroup['projects'] as $proj) {
                    foreach ($proj['external_modules'] as $em) {
                        $lines[] = [
                            $ptaGroup['pta_number'],
                            $proj['project_id'],
                            $proj['project_title'],
                            $em['module_prefix'],
                            $em['maintenance_fees'],
                            $em['instance'],
                        ];
                    }
                    // Add project subtotal row
                    $lines[] = [
                        $ptaGroup['pta_number'],
                        $proj['project_id'],
                        $proj['project_title'],
                        '** Project Subtotal **',
                        $proj['total_charges'],
                        '',
                    ];
                }
                // Add PTA subtotal row
                $lines[] = [
                    $ptaGroup['pta_number'],
                    '',
                    '',
                    '*** PTA Subtotal ***',
                    $ptaGroup['total_charges'],
                    '',
                ];
            }
        }

        // Grand total
        $lines[] = ['', '', '', '**** Grand Total ****', $reportData['grand_total'] ?? 0, ''];

        // Build CSV
        $output = fopen('php://temp', 'r+');
        foreach ($lines as $line) {
            fputcsv($output, $line);
        }
        rewind($output);
        $csv = stream_get_contents($output);
        fclose($output);
        return $csv;
    }

    /**
     * Get drill-down data for a specific PTA in a report
     * @param int $reportId
     * @param string $ptaNumber
     * @return array
     */
    public function getPTADrillDown($reportId, $ptaNumber)
    {
        $report = $this->getMonthlyPTAReportById($reportId);
        if (!$report || empty($report['report_data']['pta_groups'])) {
            return [];
        }
        foreach ($report['report_data']['pta_groups'] as $group) {
            if ($group['pta_number'] === $ptaNumber) {
                return $group;
            }
        }
        return [];
    }

    /**
     * Get month name from number
     * @param int $month
     * @return string
     */
    public function getMonthName($month)
    {
        $months = [
            1 => 'January', 2 => 'February', 3 => 'March', 4 => 'April',
            5 => 'May', 6 => 'June', 7 => 'July', 8 => 'August',
            9 => 'September', 10 => 'October', 11 => 'November', 12 => 'December',
        ];
        return $months[(int)$month] ?? '';
    }


